diff --git a/expat/lib/xmltok.c b/expat/lib/xmltok.c
index 8abb145..081c94d 100644
--- a/expat/lib/xmltok.c
+++ b/expat/lib/xmltok.c
@@ -1244,6 +1244,30 @@ doParseXmlDecl(const ENCODING *(*encodingFinder)(const ENCODING *, const char *,
       *badPtr = val;
       return 0;
     }
+    if (enc->minBytesPerChar == 1) {
+#ifndef XML_ENC_NAME_MAX
+#  define XML_ENC_NAME_MAX 127
+#endif
+      const char *const valEnd = ptr - enc->minBytesPerChar;
+      const ptrdiff_t nlen = valEnd - val;
+      if (nlen < 1 || nlen > XML_ENC_NAME_MAX) {
+        *badPtr = val;
+        return 0;
+      }
+      char encName[128];
+      memcpy(encName, val, (size_t)nlen);
+      encName[nlen] = '\0';
+      for (ptrdiff_t i = 1; i < nlen; i++) {
+        const char c2 = encName[i];
+        if (! (ASCII_a <= c2 && c2 <= ASCII_z)
+            && ! (ASCII_A <= c2 && c2 <= ASCII_Z)
+            && ! (ASCII_0 <= c2 && c2 <= ASCII_9) && c2 != ASCII_PERIOD
+            && c2 != ASCII_MINUS && c2 != ASCII_UNDERSCORE) {
+          *badPtr = val;
+          return 0;
+        }
+      }
+    }
     if (encodingName)
       *encodingName = val;
     if (encoding)

