 static const ENCODING *
 NS(findEncoding)(const ENCODING *enc, const char *ptr, const char *end) {
-#  define ENCODING_MAX 128
-  char buf[ENCODING_MAX] = "";
+  char buf[XML_ENC_NAME_MAX + 1] = "";
   char *p = buf;
